import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections = {}
    default_section = {}
    current_section = None
    current_key = None
    current_value = None

    def split_key_value(line):
        index_eq = line.find('=')
        index_colon = line.find(':')
        if index_eq == -1 and index_colon == -1:
            raise ValueError("Invalid key-value line: no '=' or ':' found")
        if index_eq == -1:
            split_index = index_colon
        elif index_colon == -1:
            split_index = index_eq
        else:
            split_index = min(index_eq, index_colon)
        key = line[:split_index].strip()
        value = line[split_index+1:].strip()
        return key, value

    def process_value(value):
        value = value.strip()
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            value = value[1:-1]
        else:
            match = re.search(r'\s+;|\s+#', value)
            if match:
                value = value[:match.start()].strip()
        return value

    def resolve_references(value, section, sections, visited):
        pattern = r'\$\{([^}]+)\}'
        matches = re.findall(pattern, value)
        if not matches:
            return value
        def replace_match(match):
            ref = match.group(1)
            if ':' in ref:
                sec_name, key_name = ref.split(':', 1)
            else:
                sec_name = section
                key_name = ref
            if sec_name not in sections:
                raise KeyError(f"Section {sec_name} not found")
            if key_name not in sections[sec_name]:
                raise KeyError(f"Key {key_name} not found in section {sec_name}")
            if (sec_name, key_name) in visited:
                raise ValueError("Cyclic reference")
            visited.add((sec_name, key_name))
            resolved_val = resolve_references(sections[sec_name][key_name], sec_name, sections, visited)
            visited.remove((sec_name, key_name))
            return resolved_val
        return re.sub(pattern, replace_match, value)

    lines = text.splitlines()
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line[0] in ';#':
            continue
        if line[0] == '[' and line[-1] == ']':
            section_name = line[1:-1].strip()
            current_section = section_name
            if current_section == 'DEFAULT':
                default_section = {}
            else:
                sections[current_section] = {}
        elif line[0] in ' \t':
            if current_key is None:
                raise ValueError("Continuation line without key")
            current_value += '\n' + line.strip()
        else:
            if current_section is None:
                raise ValueError("Key line before section header")
            key, value = split_key_value(line)
            key = key.strip().lower()
            value = process_value(value)
            if current_section == 'DEFAULT':
                default_section[key] = value
            else:
                sections[current_section][key] = value
            current_key = key
            current_value = value

    sections['DEFAULT'] = default_section
    for section in sections:
        for key in list(sections[section].keys()):
            sections[section][key] = resolve_references(sections[section][key], section, sections, set())

    result = {}
    for section in sections:
        if section == 'DEFAULT':
            continue
        merged = sections['DEFAULT'].copy()
        merged.update(sections[section])
        result[section] = merged

    return result
