def parse_duration(s: str) -> int:
    s_clean = s.strip().replace(' ', '')
    if not s_clean:
        raise ValueError("Empty string")

    tokens = []
    current_num = ''
    for char in s_clean:
        if char.isdigit():
            current_num += char
        else:
            if current_num == '':
                raise ValueError("Non-digit character without preceding number")
            unit = char.lower()
            if unit not in ['h', 'm', 's']:
                raise ValueError(f"Unknown unit: {char}")
            tokens.append((current_num, unit))
            current_num = ''

    if current_num != '':
        raise ValueError("Number without unit at the end")

    units = [unit for _, unit in tokens]
    if len(units) != len(set(units)):
        raise ValueError("Repeated unit")

    index_map = {'h': 0, 'm': 1, 's': 2}
    indices = [index_map[unit] for unit in units]
    if indices != sorted(indices):
        raise ValueError("Units out of order")

    total_seconds = 0
    for num_str, unit in tokens:
        num = int(num_str)
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        else:
            total_seconds += num

    return total_seconds
