import unicodedata

def slugify(title: str, max_len: int = 50) -> str:
    normalized = unicodedata.normalize('NFKD', title).encode('ascii', 'ignore').decode('ascii')
    normalized = normalized.lower()
    s = ''.join(['-' if not c.isalnum() else c for c in normalized])
    while '--' in s:
        s = s.replace('--', '-')
    s = s.strip('-')
    if len(s) <= max_len:
        return s
    words = s.split('-')
    if len(words[0]) > max_len:
        return words[0][:max_len]
    current_length = 0
    selected = []
    for word in words:
        if current_length == 0:
            selected.append(word)
            current_length = len(word)
        else:
            if current_length + 1 + len(word) <= max_len:
                selected.append(word)
                current_length += 1 + len(word)
            else:
                break
    return '-'.join(selected)
